changeSet.sql:
CREATE MATERIALIZED VIEW mv_daily_recon_summary AS SELECT t.trade_date, c.region, t.asset_class, COUNT(*) AS total_trades, COUNT(*) FILTER (WHERE t.status = 'MATCHED') AS matched_trades, COALESCE(SUM(rb.open_breaks), 0) AS open_breaks, COALESCE(SUM(t.quantity * t.price), 0) AS gross_notional, ROUND( 100.0 * COUNT(*) FILTER (WHERE t.status = 'MATCHED') / NULLIF(COUNT(*), 0), 2 ) AS match_rate_pct FROM trades t LEFT JOIN ( SELECT trade_id, trade_date, COUNT(*) FILTER (WHERE status = 'OPEN') AS open_breaks FROM recon_breaks GROUP BY trade_id, trade_date ) rb ON rb.trade_id = t.id AND rb.trade_date = t.trade_date INNER JOIN counterparties c ON c.id = t.counterparty_id
WHERE t.deleted_at IS NULL GROUP BY t.trade_date, c.region, t.asset_class;
CREATE UNIQUE INDEX uq_mv_daily_recon_summary_trade_date ON mv_daily_recon_summary (trade_date, region, asset_class);
